def navbar():
    source=(ROOT/'index.html').read_text(encoding='utf-8')
    m=re.search(r'(<div class="container-fluid sticky-top">.*?</nav>\s*</div>\s*</div>)', source, re.S)
    if not m: raise RuntimeError('navbar not found')
    return m.group(1)

def page(city, region, country, area, thesis, sectors, modeling, funds, local):
    slug=city.lower().replace("'",'').replace('.','').replace(' ','-')+'-business-plan-writers.html'
    nationality='Canadian' if country=='Canada' else 'US'
    fund_cards=''.join(f'''<div class="col-lg-4"><article class="border rounded-3 p-4 h-100 shadow-sm"><h3 class="h5">{escape(n)}</h3><p>{escape(d)}</p><a href="{u}" target="_blank" rel="noopener noreferrer">Check current program details <span aria-hidden="true">→</span></a></article></div>''' for n,u,d in funds)
